/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, cool checkbox, circle-checkbox */
.__UIV_SCOPE__ .checkbox-wrapper-65 *,
  .__UIV_SCOPE__ .checkbox-wrapper-65 ::after,
  .__UIV_SCOPE__ .checkbox-wrapper-65 ::before {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 .cbx {
  position: relative;
  display: block;
  float: left;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  background-color: #1c4780;
  background-image: linear-gradient(#0f698d, #1d3c6b);
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.15), inset 0 -1px 1px rgba(0,0,0,0.15);
  transition: all 0.15s ease;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 .cbx svg {
  position: absolute;
  top: 3px;
  left: 3px;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke: #fff;
  stroke-width: 2;
  stroke-dasharray: 17;
  stroke-dashoffset: 17;
  transform: translate3d(0, 0, 0);
}

.__UIV_SCOPE__ .checkbox-wrapper-65 .cbx + span {
  float: left;
  margin-left: 6px;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 {
  user-select: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 label {
  display: inline-block;
  cursor: pointer;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 input[type="checkbox"] {
  display: none;
  visibility: hidden;
}

.__UIV_SCOPE__ .checkbox-wrapper-65 input[type="checkbox"]:checked + .cbx {
  background-color: #606062;
  background-image: linear-gradient(#2584d2, #1d52c1);
}

.__UIV_SCOPE__ .checkbox-wrapper-65 input[type="checkbox"]:checked + .cbx svg {
  stroke-dashoffset: 0;
  transition: all 0.15s ease;
}
